     4	/**
     5	 * A simple model of a Grass plant.
     6	 * Grass age, breed and die.
     7	 *
     8	 * @version 2022.03.01
     9	 */
    10	public class Grass extends Plants
    11	{
    12	    // The age at which a grass plant can start to grow.
    13	    private static final int BREEDING_AGE = 1;
    14	    // The age to which a grass plant can live.
    15	    private static final int MAX_AGE = 200;
    16	    // The maximum number of sqaures new grass can grow into.
    17	    private static final int MAX_LITTER_SIZE = 500;
    18	
    19	    /**
    20	     * Create a new grass plant at location in field.
    21	     *
    22	     * @param randomAge True if a random age should be generated for the grass
    23	     * @param field The field currently occupied.
    24	     * @param location The location within the field.
    25	     */
    26	    public Grass(boolean randomAge, Field field, Location location)
    27	    {
    28	        super(field, location);
    29	        setAge(0);
    30	        if(randomAge) {
    31	            setAge(getRandom().nextInt(MAX_AGE));
    32	        } 
    33	        addGrowthLevel(getAge()/50.0);
    34	    }
    35	
    36	    /**
    37	     * Make this plant act - that is: make it do
    38	     * whatever it wants/needs to do.
    39	     * 
    40	     * @param newGrass A list to receive newly born grass.
    41	     * @param simulator The simulator.
    42	     */
    43	    public void act(List<Actor> newGrass,Simulator simulator){
    44	        incrementAge(simulator.getSteps());
    45	        addGrowthLevel(0.05);
    46	        if(simulator.isDay()){
    47	            if(isActive()) {
    48	                 Field field = getField();
    49	                //sets the location to show the grass once the actor on top of it has moved.
    50	                if (field.getObjectAt(getLocation()) == null ){
    51	                    setLocation(getLocation());
    52	                }else if (field.getObjectAt(getLocation()) != this && (field.getObjectAt(getLocation()) instanceof Plants)){
    53	                    Object grassObject = field.getObjectAt(getLocation());
    54	                    Plants grassPlant = (Plants)grassObject;
    55	                    grassPlant.setDead();
    56	                    setLocation(getLocation());
    57	
    58	                }
    59	                
    60	                switch(simulator.getWeather()){
    61	                    case SUNNY:
    62	                        increaseSunLevel();
    63	                        decreaseWaterLevel();
    64	                        break;
    65	                    case RAINY:
    66	                        increaseWaterLevel();
    67	                        decreaseSunLevel();
    68	                        break;
    69	                    case FOGGY:
    70	                        increaseWaterLevel();
    71	                        break;
    72	                    default:
    73	                        break;
    74	                }
    75	                List<Location> free = field.getFreeAdjacentLocations(getLocation());
    76	                int births = growth(simulator.getSteps());
    77	                for(int b = 0; b < births && free.size() > 0; b++) {
    78	                    Location loc = free.remove(0);
    79	                    Grass young = new Grass(false, field, loc);
    80	                    newGrass.add(young);
    81	                }
    82	            }  
    83	        }else{
    84	            //space for potential night activities
    85	        }
    86	    }
    87	
    88	    /**
    89	     * Get breeding age of a grass.
    90	     * @return int. Breeding age of the grass.
    91	     */
    92	    protected int getBreedingAge(){
    93	        return BREEDING_AGE;
    94	    }
    95	
    96	    /**
    97	     * Get max age of a grass.
    98	     * @return int. Maximum age of the grass.
    99	     */
   100	    protected int getMaxAge(){
   101	        return MAX_AGE;
   102	    }
   103	
   104	    /**
   105	     * Get max litter size of a grass.
   106	     * @return int. Maximum litter size of the grass;
   107	     */
   108	    protected int getMaxLitter(){
   109	        return MAX_LITTER_SIZE;
   110	    }
   111	}
