     1	/**
     2	 * Represent a location in a rectangular grid.
     3	 *
     4	 * @version 2016.02.29
     5	 */
     6	public class Location
     7	{
     8	    // Row and column positions.
     9	    private int row; 
    10	    private int col;
    11	
    12	    /**
    13	     * Represent a row and column.
    14	     * @param row The row.
    15	     * @param col The column.
    16	     */
    17	    public Location(int row, int col)
    18	    {
    19	        this.row = row;
    20	        this.col = col;
    21	    }
    22	    
    23	    /**
    24	     * Implement content equality.
    25	     */
    26	    public boolean equals(Object obj)
    27	    {
    28	        if(obj instanceof Location) {
    29	            Location other = (Location) obj;
    30	            return row == other.getRow() && col == other.getCol();
    31	        }
    32	        else {
    33	            return false;
    34	        }
    35	    }
    36	    
    37	    /**
    38	     * Return a string of the form row,column
    39	     * @return A string representation of the location.
    40	     */
    41	    public String toString()
    42	    {
    43	        return row + "," + col;
    44	    }
    45	    
    46	    /**
    47	     * Use the top 16 bits for the row value and the bottom for
    48	     * the column. Except for very big grids, this should give a
    49	     * unique hash code for each (row, col) pair.
    50	     * @return A hashcode for the location.
    51	     */
    52	    public int hashCode()
    53	    {
    54	        return (row << 16) + col;
    55	    }
    56	    
    57	    /**
    58	     * @return The row.
    59	     */
    60	    public int getRow()
    61	    {
    62	        return row;
    63	    }
    64	    
    65	    /**
    66	     * @return The column.
    67	     */
    68	    public int getCol()
    69	    {
    70	        return col;
    71	    }
    72	}
