     3	/**
     4	 * Provide a counter for a participant in the simulation.
     5	 * This includes an identifying string and a count of how
     6	 * many participants of this type currently exist within 
     7	 * the simulation.
     8	 *
     9	 * @version 2022.03.01
    10	 */
    11	public class Counter
    12	{
    13	    // A name for this type of simulation participant
    14	    private String name;
    15	    // How many of this type exist in the simulation.
    16	    private int count;
    17	
    18	    /**
    19	     * Provide a name for one of the simulation types.
    20	     * @param name  A name, e.g. "Jaguar".
    21	     */
    22	    public Counter(String name)
    23	    {
    24	        this.name = name;
    25	        count = 0;
    26	    }
    27	
    28	    /**
    29	     * @return The short description of this type.
    30	     */
    31	    public String getName()
    32	    {
    33	        return name;
    34	    }
    35	
    36	    /**
    37	     * @return The current count for this type.
    38	     */
    39	    public int getCount()
    40	    {
    41	        return count;
    42	    }
    43	
    44	    /**
    45	     * Increment the current count by one.
    46	     */
    47	    public void increment()
    48	    {
    49	        count++;
    50	    }
    51	
    52	    /**
    53	     * Reset the current count to zero.
    54	     */
    55	    public void reset()
    56	    {
    57	        count = 0;
    58	    }
    59	
    60	    /**
    61	     * Set the current counter to value given in parameter.
    62	     * @param value. Int value to set the count to.
    63	     */
    64	    public void setCount(int value){
    65	        count = value;
    66	    }
    67	}

